<script setup>
import { computed, ref, watch, nextTick } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import Composer from '../components/Composer.vue';
import ArtifactPreview from '../components/ArtifactPreview.vue';
import { data, ui, currentSession, currentArtifact, begin, reply, stopPreview, saveArtifact, notify, formatTime, go } from '../lib/store.js';
import { templates, typeInfo, downloadArtifact } from '../lib/artifacts.js';
const editing = ref(false), content = ref(null), title = ref(''), selected = ref('gateway'), history = ref(false), expanded = ref(false), panel = ref('artifact'), downloadOpen = ref(false), messagesEl = ref(), zoom = ref(100);
const clone = value => JSON.parse(JSON.stringify(value));
const session = currentSession, artifact = currentArtifact;
const busy = computed(() => ui.pending?.sessionId === session.value?.id);
const node = computed(() => content.value?.nodes?.find(n => n.id === selected.value));
const draftKey = computed(() => 'zflow-next-draft-' + artifact.value?.id);
const isNew = computed(() => ui.page === 'chat' || ui.page === 'office');
const defaultType = computed(() => ui.page === 'office' ? 'diagram' : 'chat');
const draft = ref(ui.draft); ui.draft = '';
watch(artifact, value => {
  if (!value || editing.value) return;
  content.value = clone(value.content); title.value = value.title;
  try { const saved = JSON.parse(sessionStorage.getItem(draftKey.value) || 'null'); if (saved) { content.value = saved.content; title.value = saved.title; editing.value = true; notify('已恢复本次浏览器中的未保存草稿'); } } catch { /* Saved artifact remains available. */ }
}, { immediate: true });
watch([content, title], () => {
  if (!editing.value || !artifact.value) return;
  try { sessionStorage.setItem(draftKey.value, JSON.stringify({ content: content.value, title: title.value })); } catch { notify('草稿无法自动保留，请及时保存作品。', true); }
}, { deep: true });
watch(() => session.value?.messages.length, async () => { await nextTick(); if (messagesEl.value) messagesEl.value.scrollTop = messagesEl.value.scrollHeight; });
function save() { if (saveArtifact(artifact.value.id, content.value, title.value)) { editing.value = false; sessionStorage.removeItem(draftKey.value); } }
function cancelEdit() { editing.value = false; content.value = clone(artifact.value.content); title.value = artifact.value.title; sessionStorage.removeItem(draftKey.value); }
function restore(revision) { if (saveArtifact(artifact.value.id, revision.content, revision.title)) { editing.value = false; sessionStorage.removeItem(draftKey.value); content.value = clone(revision.content); title.value = revision.title; history.value = false; } }
function download(format) { if (editing.value) { notify('请保存修改后再导出，或取消编辑以导出已保存的版本。'); return; } downloadArtifact(artifact.value, format); downloadOpen.value = false; }
async function copyConversation() { try { await navigator.clipboard.writeText(session.value.messages.map(m => (m.role === 'user' ? '我' : 'ZFlow（示例回复）') + '\n' + m.text).join('\n\n')); notify('对话已复制'); } catch { notify('浏览器未允许复制，请手动选择对话内容。', true); } }
function startFromTemplate(template) { begin({ prompt: template.prompt, type: template.type, templateId: template.id }); }
</script>
<template>
  <div v-if="isNew" class="new-workspace page"><div class="new-workspace-mark"><Icon :name="ui.page === 'office' ? 'Workflow' : 'MessageSquare'" :size="27" /></div><span class="small-label">{{ ui.page === 'office' ? '智能办公' : '自由对话' }}</span><h1>{{ ui.page === 'office' ? '把想法，变成可编辑的作品。' : '有什么想一起想清楚的？' }}</h1><p>{{ ui.page === 'office' ? '图表、文档与任务清单，从一句需求开始。' : '提问、推敲，或展开一个新的想法。' }}</p><Composer :default-type="defaultType" :initial="draft" @submit="begin" /><div class="new-workspace-templates"><button v-for="template in templates" :key="template.id" @click="startFromTemplate(template)"><Icon :name="template.icon" :size="22" /><strong>{{ template.title }}</strong><span>打开可编辑示例 <Icon name="ArrowUpRight" :size="14" /></span></button></div><p class="preview-caption"><Icon name="Eye" :size="14" />设计预览 · 回复与初始作品为示例</p></div>
  <div v-else-if="session" class="workspace-layout" :class="{ 'has-artifact': artifact, expanded, 'show-conversation': panel === 'conversation' }">
    <div v-if="artifact" class="mobile-panel-tabs"><button :class="{ active: panel === 'conversation' }" @click="panel = 'conversation'">对话</button><button :class="{ active: panel === 'artifact' }" @click="panel = 'artifact'">作品</button></div>
    <section class="conversation-panel"><header class="conversation-header"><span class="file-icon small"><Icon :name="typeInfo[session.type]?.icon" :size="17" /></span><h1 :title="session.title">{{ session.title }}</h1><button class="icon-button" aria-label="复制对话" @click="copyConversation"><Icon name="Copy" :size="16" /></button></header>
      <div ref="messagesEl" class="messages"><div class="conversation-date">{{ formatTime(session.updatedAt) }}<span>本地预览</span></div><article v-for="message in session.messages" :key="message.id" class="message" :class="message.role"><template v-if="message.role === 'user'"><div class="message-body">{{ message.text }}</div><div v-if="message.attachments?.length" class="message-attachments"><span v-for="file in message.attachments" :key="file"><Icon name="Paperclip" :size="12" />{{ file }}</span></div><div v-if="message.sourceIds?.length" class="message-sources"><Icon name="BookOpen" :size="12" />已选择 {{ message.sourceIds.length }} 份资料 · 预览不执行检索</div></template><template v-else><div class="assistant-name"><img src="/favicon.svg" alt="" /><strong>ZFlow</strong><span>示例回复</span></div><div class="message-body">{{ message.text }}</div><button v-if="artifact" class="message-artifact" @click="panel = 'artifact'; expanded = false"><span class="file-icon"><Icon :name="typeInfo[artifact.type]?.icon" :size="20" /></span><span><strong>{{ artifact.title }}</strong><small>{{ typeInfo[artifact.type]?.label }} · 可编辑示例</small></span><Icon name="ArrowUpRight" :size="17" /></button></template></article>
        <div v-if="busy" class="preview-progress" role="status"><span class="loading-symbol"><Icon name="LoaderCircle" :size="19" /></span><div><strong>正在准备{{ typeInfo[session.type]?.label }}预览</strong><p>载入示例内容与编辑工作区…</p></div></div><div v-else-if="session.status === 'cancelled' || (session.status === 'preparing' && !busy)" class="info-note"><Icon name="CircleAlert" /><p>示例准备已中断。<button class="text-button" @click="begin({ prompt: session.messages[0].text, type: session.type })">重新打开示例</button></p></div>
      </div><div class="conversation-composer"><Composer compact followup :busy="busy" @submit="v => reply(session.id, v.prompt)" @stop="stopPreview" /><span class="preview-caption">设计预览中的 AI 回复为示例内容</span></div>
    </section>
    <section v-if="artifact" class="artifact-panel"><header class="artifact-header"><span class="artifact-file-symbol"><Icon :name="typeInfo[artifact.type]?.icon" :size="18" /></span><div class="artifact-header-name"><input v-if="editing" v-model="title" aria-label="作品名称" maxlength="100" /><strong v-else :title="artifact.title">{{ artifact.title }}</strong><span>{{ editing ? '有未保存的修改' : '已保存到本地' }}<i></i>v{{ artifact.revisions.length }}</span></div><button class="icon-button" :aria-label="expanded ? '退出大画布' : '展开画布'" @click="expanded = !expanded"><Icon :name="expanded ? 'Minimize2' : 'Maximize2'" :size="17" /></button></header>
      <div class="artifact-toolbar"><div class="artifact-view-label"><Icon :name="editing ? 'Pencil' : 'Eye'" :size="15" /><span>{{ editing ? '编辑作品' : '作品预览' }}</span><span class="subtle-tag">示例</span></div><div class="artifact-actions"><template v-if="editing"><button class="secondary-button small" @click="cancelEdit">取消</button><button class="primary-button small" @click="save"><Icon name="Check" :size="14" />保存</button></template><template v-else><button class="icon-button" aria-label="版本历史" title="版本历史" @click="history = true"><Icon name="History" :size="17" /></button><button class="secondary-button small" @click="editing = true"><Icon name="Pencil" :size="14" />编辑</button><div class="download-menu"><button class="primary-button small" @click="artifact.type === 'diagram' ? downloadOpen = !downloadOpen : download()" :aria-expanded="artifact.type === 'diagram' ? downloadOpen : undefined"><Icon name="Download" :size="14" />导出<Icon v-if="artifact.type === 'diagram'" name="ChevronDown" :size="12" /></button><div v-if="downloadOpen" class="dropdown-menu"><button @click="download('svg')"><Icon name="File" :size="15" />SVG 图片</button><button @click="download('drawio')"><Icon name="Workflow" :size="15" />draw.io 源文件</button></div></div></template></div></div>
      <div class="artifact-canvas" :class="artifact.type"><textarea v-if="editing && artifact.type === 'document'" v-model="content.text" class="document-editor" aria-label="文档内容" spellcheck="false" /><div v-else class="canvas-inner" :style="artifact.type === 'diagram' ? { width: zoom + '%' } : undefined"><ArtifactPreview :type="artifact.type" :content="content || artifact.content" :editable="editing" :selected="editing ? selected : undefined" @select="selected = $event" @change="content = $event" /></div>
        <div v-if="editing && artifact.type === 'diagram' && node" class="node-properties"><strong><Icon name="SlidersHorizontal" :size="15" />节点属性</strong><label>名称<input v-model="node.label" maxlength="24" /></label><label>说明<input v-model="node.detail" maxlength="36" /></label><small>点击图中的其他节点继续编辑</small></div>
      </div><footer class="artifact-footer"><span><Icon name="CheckCheck" :size="14" />{{ editing ? '草稿保留在本次浏览器会话' : `已保留 ${artifact.revisions.length} 个版本` }}</span><div v-if="artifact.type === 'diagram'" class="zoom-control"><button aria-label="缩小画布" :disabled="zoom <= 60" @click="zoom -= 20"><Icon name="Minimize2" :size="13" /></button><button title="重置缩放" @click="zoom = 100">{{ zoom }}%</button><button aria-label="放大画布" :disabled="zoom >= 180" @click="zoom += 20"><Icon name="Plus" :size="13" /></button></div><span v-else>{{ artifact.type === 'document' ? 'Markdown 文档' : `${artifact.content.rows.length} 行 · ${artifact.content.columns.length} 列` }}</span></footer>
    </section>
  </div>
  <div v-else class="empty-state page"><Icon name="FolderOpen" :size="36" /><h1>没有找到这段对话</h1><p>记录可能已删除，或保存在其他浏览器中。</p><button class="primary-button" @click="go('home')">回到工作台</button></div>
  <Modal v-if="history && artifact" title="版本历史" @close="history = false"><p class="muted">恢复会创建新版本，之前的记录会完整保留。</p><div class="version-list"><div v-for="version in [...artifact.revisions].reverse()" :key="version.version" class="version-row"><span class="version-dot"></span><div><strong>版本 {{ version.version }}<span v-if="version.version === artifact.revisions.length" class="subtle-tag">当前</span></strong><p>{{ version.title }}</p><time>{{ formatTime(version.date) }}</time></div><button v-if="version.version !== artifact.revisions.length" class="secondary-button small" @click="restore(version)"><Icon name="RotateCcw" :size="13" />恢复</button></div></div></Modal>
</template>
